def policy(obs,P):
    x,y,vx,vy,angle,ang_v,leg_left,leg_right = obs
    if y <= P['y0'] or leg_left>0.5 or leg_right>0.5:
        if vx < P['vx_thr'] and angle < P['ang_thr_g']:
            return 3
        return 1
    at = x*P['c1'] + vx*P['c2']
    lim = P['c_lim']
    if at > lim:
        at = lim
    if at < -lim:
        at = -lim
    ang_todo = (at - angle)*P['ap'] - ang_v*P['ad']
    if ang_todo > P['athr']:
        return 3
    if ang_todo < -P['athr']:
        return 1
    ht = P['h0'] + abs(x)*P['hx']
    hov_todo = (ht - y)*P['hp'] - vy*P['hd']
    if hov_todo > P['hthr']:
        return 2
    return 0
